#!/bin/bash\n# Sequoia-X 量化选股系统 - 日常运行脚本\nPROJECT_DIR="$(cd "$(dirname "$0")" && pwd)"\nLOG_FILE="$PROJECT_DIR/log.txt"\necho "======================================" >> "$LOG_FILE"\necho "$(date '+%Y-%m-%d %H:%M:%S') - 开始运行 Sequoia-X" >> "$LOG_FILE"\necho "======================================" >> "$LOG_FILE"\ncd "$PROJECT_DIR"\npython3 main.py >> "$LOG_FILE" 2>&1\necho "" >> "$LOG_FILE"\necho "$(date '+%Y-%m-%d %H:%M:%S') - 运行完成" >> "$LOG_FILE"\necho "" >> "$LOG_FILE"\n